From 96679913eaceab392bf1fdf0bc1c6935d2ea16d7 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 22:10:46 +0100
Subject: [PATCH] settings: keep the Ethernet setting of bond connections

NetworkManager keeps a bond's MTU and cloned MAC address in its Ethernet
setting, but bond connections didn't include it, so it was ignored when
reading a bond and lost when saving it back. Add it to bond connections.

BUG: 470148
---
 src/settings/connectionsettings.cpp | 2 ++
 1 file changed, 2 insertions(+)

diff --git a/src/settings/connectionsettings.cpp b/src/settings/connectionsettings.cpp
index d76a7d2..2b9582d 100644
--- a/src/settings/connectionsettings.cpp
+++ b/src/settings/connectionsettings.cpp
@@ -104,6 +104,7 @@ void NetworkManager::ConnectionSettingsPrivate::initSettings(NMBluetoothCapabili
         addSetting(Setting::Ptr(new BondSetting()));
         addSetting(Setting::Ptr(new Ipv4Setting()));
         addSetting(Setting::Ptr(new Ipv6Setting()));
+        addSetting(Setting::Ptr(new WiredSetting()));
         break;
     case ConnectionSettings::Bluetooth:
         addSetting(Setting::Ptr(new BluetoothSetting()));
@@ -236,6 +237,7 @@ void NetworkManager::ConnectionSettingsPrivate::initSettings(const NetworkManage
         addSetting(connectionSettings->setting(Setting::Bond));
         addSetting(connectionSettings->setting(Setting::Ipv4));
         addSetting(connectionSettings->setting(Setting::Ipv6));
+        addSetting(connectionSettings->setting(Setting::Wired));
         break;
     case ConnectionSettings::Bluetooth:
         addSetting(connectionSettings->setting(Setting::Bluetooth));
-- 
